1	import jsPDF, { GState } from 'jspdf';
2	import autoTable from 'jspdf-autotable';
3	import { format } from 'date-fns';
4	import { ptBR } from 'date-fns/locale';
5	
6	// ───────────────────────── TIPOS PÚBLICOS ─────────────────────────
7	
8	export interface PerdasEntry {
9	  val: number;        // valor_estimado
10	  qty: number;        // quantidade
11	  prod: string;       // produto_nome_perda
12	  store: string;      // stores?.nome
13	  date: string | null;
14	  motivo_perda: string;
15	  unidade?: string | null;
16	}
17	
18	export interface PerdasAggregate {
19	  totalValue: number;
20	  totalRecords: number;
21	  /** totalValue / totalRecords, 0 se vazio */
22	  ticketMedio: number;
23	  /** produto com maior totalValue, "-" se vazio */
24	  produtoCritico: string;
25	  /** ordenado por value desc */
26	  byMotivo: Array<{ motivo: string; count: number; value: number; pct: number }>;
27	  /** top 10 por valor, rank 1-10 */
28	  top10Produtos: Array<{ rank: number; produto: string; qty: number; value: number }>;
29	}
30	
31	export interface GeneratePerdasPdfParams {
32	  entries: PerdasEntry[];
33	  periodoLabel: string;  // ex: "01/05/2026 – 31/05/2026"
34	  lojaLabel: string;     // ex: "Momma Asa Sul" ou "Todas as lojas"
35	  motivosLabel: string;  // ex: "Vencido, Quebra" ou "Todos"
36	}
37	
38	// ───────────────────────── HELPER PURO (TESTÁVEL) ─────────────────────────
39	
40	export function aggregatePerdas(entries: PerdasEntry[]): PerdasAggregate {
41	  if (entries.length === 0) {
42	    return {
43	      totalValue: 0,
44	      totalRecords: 0,
45	      ticketMedio: 0,
46	      produtoCritico: '-',
47	      byMotivo: [],
48	      top10Produtos: [],
49	    };
50	  }
51	
52	  const totalValue = entries.reduce((s, e) => s + e.val, 0);
53	  const totalRecords = entries.length;
54	
55	  // Agrega por motivo
56	  const motivoMap = new Map<string, { count: number; value: number }>();
57	  for (const e of entries) {
58	    const m = e.motivo_perda || 'Não Informado';
59	    const cur = motivoMap.get(m) ?? { count: 0, value: 0 };
60	    motivoMap.set(m, { count: cur.count + 1, value: cur.value + e.val });
61	  }
62	
63	  const byMotivo = Array.from(motivoMap.entries())
64	    .map(([motivo, d]) => ({
65	      motivo,
66	      count: d.count,
67	      value: d.value,
68	      pct: totalValue > 0 ? (d.value / totalValue) * 100 : 0,
69	    }))
70	    .sort((a, b) => b.value - a.value);
71	
72	  // Agrega por produto (valor e qtd)
73	  const prodMap = new Map<string, { qty: number; value: number }>();
74	  for (const e of entries) {
75	    const p = e.prod || 'Desconhecido';
76	    const cur = prodMap.get(p) ?? { qty: 0, value: 0 };
77	    prodMap.set(p, { qty: cur.qty + e.qty, value: cur.value + e.val });
78	  }
79	
80	  const sortedProds = Array.from(prodMap.entries())
81	    .sort((a, b) => b[1].value - a[1].value);
82	
83	  const produtoCritico = sortedProds.length > 0 ? sortedProds[0][0] : '-';
84	
85	  const top10Produtos = sortedProds.slice(0, 10).map(([produto, d], i) => ({
86	    rank: i + 1,
87	    produto,
88	    qty: d.qty,
89	    value: d.value,
90	  }));
91	
92	  return {
93	    totalValue,
94	    totalRecords,
95	    ticketMedio: totalRecords > 0 ? totalValue / totalRecords : 0,
96	    produtoCritico,
97	    byMotivo,
98	    top10Produtos,
99	  };
100	}
101	
102	// ───────────────────────── HELPERS LOCAIS DE PDF ─────────────────────────
103	// Replicados (não importados de outra feature) para respeitar boundaries FSD.
104	
105	const MOMMA_GREEN: [number, number, number] = [87, 113, 91];
106	const MOMMA_GREEN_DARK: [number, number, number] = [30, 37, 31];
107	const MOMMA_GREEN_SOFT: [number, number, number] = [74, 85, 76];
108	
109	const currencyFmt = (v: number): string =>
110	  v.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
111	
112	const pctFmt = (v: number): string =>
113	  v.toLocaleString('pt-BR', { minimumFractionDigits: 1, maximumFractionDigits: 1 }) + '%';
114	
115	const qtyFmt = (v: number): string =>
116	  v.toLocaleString('pt-BR', { minimumFractionDigits: 0, maximumFractionDigits: 2 });
117	
118	const loadImage = (url: string): Promise<HTMLImageElement> =>
119	  new Promise((resolve, reject) => {
120	    const img = new Image();
121	    img.crossOrigin = 'Anonymous';
122	    img.onload = () => resolve(img);
123	    img.onerror = () => reject(new Error(`Failed to load image: ${url}`));
124	    img.src = url;
125	  });
126	
127	// ───────────────────────── GERADOR DE PDF ─────────────────────────
128	
129	export async function generatePerdasPdf(params: GeneratePerdasPdfParams): Promise<void> {
130	  const { entries, periodoLabel, lojaLabel, motivosLabel } = params;
131	  const agg = aggregatePerdas(entries);
132	
133	  const logoHeader = await loadImage('/logo sistema/01. Reduzida 5.png').catch(() => null);
134	  const watermarkLogo = await loadImage('/logo sistema/android-chrome-512x512.png').catch(() => null);
135	
136	  const doc = new jsPDF('p', 'mm', 'a4');
137	  const pageWidth = doc.internal.pageSize.getWidth();
138	  const pageHeight = doc.internal.pageSize.getHeight();
139	
140	  // ───────────────────────── HEADER, FOOTER & WATERMARK POR PÁGINA ─────────────────────────
141	  const drawPageExtras = (hookData: { pageNumber?: number }) => {
142	    const currentPage = hookData.pageNumber || 1;
143	
144	    // Bordas premium (dupla linha)
145	    doc.setDrawColor(...MOMMA_GREEN);
146	    doc.setLineWidth(0.5);
147	    doc.roundedRect(10, 10, pageWidth - 20, pageHeight - 20, 2, 2, 'S');
148	    doc.setLineWidth(0.2);
149	    doc.roundedRect(12, 12, pageWidth - 24, pageHeight - 24, 2, 2, 'S');
150	
151	    // Logo cabeçalho — preserva aspect ratio, max 18mm altura
152	    if (logoHeader) {
153	      const ratio = logoHeader.height / logoHeader.width;
154	      let expectedWidth = 45;
155	      let expectedHeight = expectedWidth * ratio;
156	      if (expectedHeight > 18) {
157	        expectedHeight = 18;
158	        expectedWidth = expectedHeight / ratio;
159	      }
160	      doc.addImage(logoHeader, 'PNG', 15, 15, expectedWidth, expectedHeight);
161	    }
162	
163	    // Título e subtítulo (alinhados à direita)
164	    doc.setFont('helvetica', 'bold');
165	    doc.setTextColor(...MOMMA_GREEN_DARK);
166	    doc.setFontSize(16);
167	    doc.text('RELATÓRIO DE PERDAS', pageWidth - 15, 20, { align: 'right' });
168	
169	    doc.setFont('helvetica', 'normal');
170	    doc.setFontSize(9);
171	    doc.setTextColor(...MOMMA_GREEN);
172	    doc.text('ANÁLISE ESTRATÉGICA', pageWidth - 15, 25, { align: 'right' });
173	
174	    doc.setTextColor(...MOMMA_GREEN_SOFT);
175	    doc.setFontSize(8);
176	    doc.text(`Período: ${periodoLabel}`, pageWidth - 15, 31, { align: 'right' });
177	    doc.text(`Loja: ${lojaLabel}`, pageWidth - 15, 35, { align: 'right' });
178	    doc.text(`Motivos: ${motivosLabel}`, pageWidth - 15, 39, { align: 'right' });
179	
180	    // Linha separadora abaixo do header
181	    doc.setDrawColor(...MOMMA_GREEN);
182	    doc.setLineWidth(0.5);
183	    doc.line(15, 43, pageWidth - 15, 43);
184	
185	    // Footer com paginação
186	    doc.setFont('helvetica', 'normal');
187	    doc.setFontSize(8);
188	    doc.setTextColor(...MOMMA_GREEN);
189	    const totalPages = doc.getNumberOfPages();
190	    doc.text(
191	      `Relatório de Perdas Momma • Emissão: ${format(new Date(), "dd/MM/yyyy 'às' HH:mm", { locale: ptBR })} • Pág. ${currentPage}/${totalPages}`,
192	      pageWidth / 2,
193	      pageHeight - 12,
194	      { align: 'center' },
195	    );
196	
197	    // Watermark sutil ao centro
198	    if (watermarkLogo) {
199	      try {
200	        doc.setGState(new GState({ opacity: 0.08 }));
201	        const wSize = 200;
202	        doc.addImage(
203	          watermarkLogo,
204	          'PNG',
205	          (pageWidth - wSize) / 2,
206	          (pageHeight - wSize) / 2,
207	          wSize,
208	          wSize,
209	        );
210	        doc.setGState(new GState({ opacity: 1.0 }));
211	      } catch {
212	        /* fallback silencioso */
213	      }
214	    }
215	  };
216	
217	  // Página 1: header desenhado manualmente (resumo é desenhado fora do autoTable)
218	  drawPageExtras({ pageNumber: 1 });
219	
220	  // ───────────────────────── RESUMO EXECUTIVO ─────────────────────────
221	  let cursorY = 52;
222	
223	  doc.setFont('helvetica', 'bold');
224	  doc.setFontSize(11);
225	  doc.setTextColor(...MOMMA_GREEN);
226	  doc.text('RESUMO EXECUTIVO DO PERÍODO', 15, cursorY);
227	  cursorY += 5;
228	
229	  const boxX = 15;
230	  const boxW = pageWidth - 30;
231	  const boxH = 22;
232	
233	  doc.setFillColor(248, 250, 248);
234	  doc.setDrawColor(...MOMMA_GREEN);
235	  doc.setLineWidth(0.4);
236	  doc.roundedRect(boxX, cursorY, boxW, boxH, 2, 2, 'FD');
237	
238	  const colW = boxW / 4;
239	
240	  const drawMetric = (label: string, value: string, colIndex: number) => {
241	    doc.setFont('helvetica', 'normal');
242	    doc.setFontSize(8);
243	    doc.setTextColor(120, 120, 120);
244	    doc.text(label, boxX + colW * colIndex + 4, cursorY + 6);
245	    doc.setFont('helvetica', 'bold');
246	    doc.setFontSize(11);
247	    doc.setTextColor(...MOMMA_GREEN_DARK);
248	    // Truncar valores longos para caber na célula
249	    const maxWidth = colW - 8;
250	    const truncated = doc.getStringUnitWidth(value) * 11 / doc.internal.scaleFactor > maxWidth
251	      ? value.substring(0, 18) + '…'
252	      : value;
253	    doc.text(truncated, boxX + colW * colIndex + 4, cursorY + 14);
254	  };
255	
256	  drawMetric('PREJUÍZO TOTAL', currencyFmt(agg.totalValue), 0);
257	  drawMetric('REGISTROS', String(agg.totalRecords), 1);
258	  drawMetric('TICKET MÉDIO', currencyFmt(agg.ticketMedio), 2);
259	  // Trunca produto crítico a 20 chars
260	  const prodLabel = agg.produtoCritico.length > 20
261	    ? agg.produtoCritico.substring(0, 20) + '…'
262	    : agg.produtoCritico;
263	  drawMetric('PRODUTO CRÍTICO', prodLabel, 3);
264	
265	  cursorY += boxH + 8;
266	
267	  // ───────────────────────── SEÇÃO 2: DISTRIBUIÇÃO POR MOTIVO ─────────────────────────
268	  doc.setFont('helvetica', 'bold');
269	  doc.setFontSize(11);
270	  doc.setTextColor(...MOMMA_GREEN);
271	  doc.text('DISTRIBUIÇÃO POR MOTIVO', 15, cursorY);
272	  cursorY += 3;
273	
274	  const motivoBody = agg.byMotivo.map((m) => [
275	    m.motivo,
276	    String(m.count),
277	    currencyFmt(m.value),
278	    pctFmt(m.pct),
279	  ]);
280	
281	  // Linha de total ao final
282	  motivoBody.push([
283	    'TOTAL',
284	    String(agg.totalRecords),
285	    currencyFmt(agg.totalValue),
286	    '100,0%',
287	  ]);
288	
289	  autoTable(doc, {
290	    startY: cursorY,
291	    head: [['Motivo', 'Registros', 'Valor (R$)', '% do Total']],
292	    body: motivoBody,
293	    theme: 'plain',
294	    styles: {
295	      fontSize: 8,
296	      font: 'helvetica',
297	      cellPadding: { top: 1.8, bottom: 1.8, left: 2, right: 2 },
298	      textColor: [60, 60, 60],
299	      lineColor: [230, 230, 230],
300	      lineWidth: { bottom: 0.1 },
301	    },
302	    headStyles: {
303	      fillColor: MOMMA_GREEN,
304	      textColor: [255, 255, 255],
305	      fontStyle: 'bold',
306	      fontSize: 8.5,
307	      cellPadding: { top: 2.5, bottom: 2.5, left: 2, right: 2 },
308	      lineWidth: 0,
309	    },
310	    alternateRowStyles: { fillColor: [248, 250, 248] },
311	    columnStyles: {
312	      0: { cellWidth: 'auto' },
313	      1: { cellWidth: 25, halign: 'right' },
314	      2: { cellWidth: 40, halign: 'right', fontStyle: 'bold' },
315	      3: { cellWidth: 22, halign: 'right' },
316	    },
317	    didParseCell: (data) => {
318	      // Última linha = TOTAL em destaque
319	      if (data.section === 'body' && data.row.index === motivoBody.length - 1) {
320	        data.cell.styles.fontStyle = 'bold';
321	        data.cell.styles.fillColor = [236, 242, 237];
322	        data.cell.styles.textColor = MOMMA_GREEN_DARK;
323	      }
324	    },
325	    didDrawPage: (hk) => {
326	      if (hk.pageNumber > 1) drawPageExtras(hk);
327	    },
328	    margin: { top: 50, left: 15, right: 15, bottom: 20 },
329	  });
330	
331	  // Captura Y final da tabela anterior para posicionar a próxima seção
332	  // eslint-disable-next-line @typescript-eslint/no-explicit-any
333	  cursorY = (doc as any).lastAutoTable.finalY + 8;
334	
335	  // ───────────────────────── SEÇÃO 3: TOP 10 PRODUTOS ─────────────────────────
336	  // Verificar se há espaço suficiente na página atual; se não, adicionar página
337	  if (cursorY + 15 > pageHeight - 25) {
338	    doc.addPage();
339	    drawPageExtras({ pageNumber: doc.getNumberOfPages() });
340	    cursorY = 52;
341	  }
342	
343	  doc.setFont('helvetica', 'bold');
344	  doc.setFontSize(11);
345	  doc.setTextColor(...MOMMA_GREEN);
346	  doc.text('TOP 10 PRODUTOS POR PREJUÍZO', 15, cursorY);
347	  cursorY += 3;
348	
349	  const top10Body = agg.top10Produtos.map((p) => [
350	    String(p.rank),
351	    p.produto,
352	    qtyFmt(p.qty),
353	    currencyFmt(p.value),
354	  ]);
355	
356	  autoTable(doc, {
357	    startY: cursorY,
358	    head: [['#', 'Produto', 'Qtd', 'Valor (R$)']],
359	    body: top10Body,
360	    theme: 'plain',
361	    styles: {
362	      fontSize: 8,
363	      font: 'helvetica',
364	      cellPadding: { top: 1.8, bottom: 1.8, left: 2, right: 2 },
365	      textColor: [60, 60, 60],
366	      lineColor: [230, 230, 230],
367	      lineWidth: { bottom: 0.1 },
368	    },
369	    headStyles: {
370	      fillColor: MOMMA_GREEN,
371	      textColor: [255, 255, 255],
372	      fontStyle: 'bold',
373	      fontSize: 8.5,
374	      cellPadding: { top: 2.5, bottom: 2.5, left: 2, right: 2 },
375	      lineWidth: 0,
376	    },
377	    alternateRowStyles: { fillColor: [248, 250, 248] },
378	    columnStyles: {
379	      0: { cellWidth: 12, halign: 'center', fontStyle: 'bold' },
380	      1: { cellWidth: 'auto' },
381	      2: { cellWidth: 25, halign: 'right' },
382	      3: { cellWidth: 40, halign: 'right', fontStyle: 'bold' },
383	    },
384	    didDrawPage: (hk) => {
385	      if (hk.pageNumber > 1) drawPageExtras(hk);
386	    },
387	    margin: { top: 50, left: 15, right: 15, bottom: 20 },
388	  });
389	
390	  // ───────────────────────── PERSISTÊNCIA ─────────────────────────
391	  // Slugifica periodoLabel substituindo caracteres não-alfanuméricos
392	  const slug = periodoLabel.replace(/[^a-zA-Z0-9]/g, '_');
393	  doc.save(`perdas_${slug}.pdf`);
394	}
