1	import jsPDF, { GState } from 'jspdf';
2	import autoTable from 'jspdf-autotable';
3	import { format } from 'date-fns';
4	import { ptBR } from 'date-fns/locale';
5	
6	/**
7	 * Gerador de Relatório PDF de Produção Diária.
8	 *
9	 * Relatório de alto nível: totais por produto, consolidado de TODAS as lojas.
10	 * Segue o padrão visual world-class do Cofre/DRE: border Momma green dupla,
11	 * logo header, watermark central, header/footer por página com paginação,
12	 * resumo executivo e tabela analítica paginada.
13	 *
14	 * O helper `aggregateProducao` é PURO (sem jsPDF) e testável isoladamente.
15	 */
16	
17	// ───────────────────────── TIPOS PÚBLICOS ─────────────────────────
18	
19	export interface ProducaoEntry {
20	  date: string;
21	  product_name: string;
22	  quantity: number;
23	}
24	
25	export interface ProducaoAggregate {
26	  totalQuantity: number;
27	  /** Nº de produtos distintos (por nome). */
28	  distinctProducts: number;
29	  /** Nº de datas distintas com produção. */
30	  activeDays: number;
31	  /** totalQuantity / activeDays (0 se activeDays = 0). */
32	  avgPerDay: number;
33	  /** Ordenado por quantity desc, depois nome asc. */
34	  byProduct: Array<{ product_name: string; quantity: number }>;
35	}
36	
37	export interface GenerateProducaoDiariaPdfParams {
38	  entries: ProducaoEntry[];
39	  dateStart: string; // yyyy-MM-dd
40	  dateEnd: string; // yyyy-MM-dd
41	}
42	
43	// ───────────────────────── HELPER PURO (TESTÁVEL) ─────────────────────────
44	
45	/**
46	 * Agrega lançamentos de produção em totais de alto nível.
47	 *
48	 * - Produtos com mesmo nome têm suas quantidades somadas.
49	 * - Dias são contados por datas distintas (mesma data conta 1).
50	 * - Lista vazia retorna tudo zerado e arrays vazios.
51	 */
52	export function aggregateProducao(entries: ProducaoEntry[]): ProducaoAggregate {
53	  const productTotals = new Map<string, number>();
54	  const distinctDates = new Set<string>();
55	  let totalQuantity = 0;
56	
57	  for (const entry of entries) {
58	    const quantity = Number(entry.quantity) || 0;
59	    totalQuantity += quantity;
60	
61	    const productKey = entry.product_name;
62	    productTotals.set(productKey, (productTotals.get(productKey) ?? 0) + quantity);
63	
64	    if (entry.date) {
65	      distinctDates.add(entry.date);
66	    }
67	  }
68	
69	  const activeDays = distinctDates.size;
70	
71	  const byProduct = Array.from(productTotals.entries())
72	    .map(([product_name, quantity]) => ({ product_name, quantity }))
73	    .sort((a, b) => {
74	      if (b.quantity !== a.quantity) return b.quantity - a.quantity;
75	      return a.product_name.localeCompare(b.product_name, 'pt-BR');
76	    });
77	
78	  return {
79	    totalQuantity,
80	    distinctProducts: productTotals.size,
81	    activeDays,
82	    avgPerDay: activeDays === 0 ? 0 : totalQuantity / activeDays,
83	    byProduct,
84	  };
85	}
86	
87	// ───────────────────────── HELPERS LOCAIS DE PDF ─────────────────────────
88	// Replicados (não importados de outra feature) para respeitar boundaries FSD.
89	
90	const MOMMA_GREEN: [number, number, number] = [87, 113, 91];
91	const MOMMA_GREEN_DARK: [number, number, number] = [30, 37, 31];
92	const MOMMA_GREEN_SOFT: [number, number, number] = [74, 85, 76];
93	
94	/**
95	 * Quantidades podem ser fracionárias (ex.: 0.5). Mostra até 2 casas decimais,
96	 * suprimindo zeros à direita (inteiros ficam sem casas).
97	 */
98	const numberFmt = (v: number): string =>
99	  v.toLocaleString('pt-BR', { minimumFractionDigits: 0, maximumFractionDigits: 2 });
100	
101	const avgFmt = (v: number): string =>
102	  v.toLocaleString('pt-BR', { minimumFractionDigits: 1, maximumFractionDigits: 1 });
103	
104	const loadImage = (url: string): Promise<HTMLImageElement> =>
105	  new Promise((resolve, reject) => {
106	    const img = new Image();
107	    img.crossOrigin = 'Anonymous';
108	    img.onload = () => resolve(img);
109	    img.onerror = () => reject(new Error(`Failed to load image: ${url}`));
110	    img.src = url;
111	  });
112	
113	// ───────────────────────── GERADOR DE PDF ─────────────────────────
114	
115	export async function generateProducaoDiariaPdf(
116	  params: GenerateProducaoDiariaPdfParams,
117	): Promise<void> {
118	  const { entries, dateStart, dateEnd } = params;
119	  const agg = aggregateProducao(entries);
120	
121	  const logoHeader = await loadImage('/logo sistema/01. Reduzida 5.png').catch(
122	    () => null,
123	  );
124	  const watermarkLogo = await loadImage(
125	    '/logo sistema/android-chrome-512x512.png',
126	  ).catch(() => null);
127	
128	  const doc = new jsPDF('p', 'mm', 'a4');
129	  const pageWidth = doc.internal.pageSize.getWidth();
130	  const pageHeight = doc.internal.pageSize.getHeight();
131	
132	  const periodoLabel = `${format(
133	    new Date(dateStart + 'T12:00:00'),
134	    'dd/MM/yyyy',
135	    { locale: ptBR },
136	  )} a ${format(new Date(dateEnd + 'T12:00:00'), 'dd/MM/yyyy', { locale: ptBR })}`;
137	
138	  // ───────────────────────── HEADER, FOOTER & WATERMARK POR PÁGINA ─────────────────────────
139	  const drawPageExtras = (hookData: { pageNumber?: number }) => {
140	    const currentPage = hookData.pageNumber || 1;
141	
142	    // Bordas premium (dupla linha)
143	    doc.setDrawColor(...MOMMA_GREEN);
144	    doc.setLineWidth(0.5);
145	    doc.roundedRect(10, 10, pageWidth - 20, pageHeight - 20, 2, 2, 'S');
146	    doc.setLineWidth(0.2);
147	    doc.roundedRect(12, 12, pageWidth - 24, pageHeight - 24, 2, 2, 'S');
148	
149	    // Logo cabeçalho — preserva aspect ratio
150	    if (logoHeader) {
151	      const ratio = logoHeader.height / logoHeader.width;
152	      let expectedWidth = 45;
153	      let expectedHeight = expectedWidth * ratio;
154	      if (expectedHeight > 18) {
155	        expectedHeight = 18;
