import jsPDF, { GState } from 'jspdf';
import autoTable from 'jspdf-autotable';
import { format, addDays } from 'date-fns';
import { ptBR } from 'date-fns/locale';

// ───────────────────────── TIPOS PÚBLICOS ─────────────────────────

export interface PerdasEntry {
  val: number;        // valor_estimado
  qty: number;        // quantidade
  prod: string;       // produto_nome_perda
  store: string;      // stores?.nome
  date: string | null;
  motivo_perda: string;
  unidade?: string | null;
}

export interface PerdasAggregate {
  totalValue: number;
  totalRecords: number;
  /** totalValue / totalRecords, 0 se vazio */
  ticketMedio: number;
  /** produto com maior totalValue, "-" se vazio */
  produtoCritico: string;
  /** ordenado por value desc */
  byMotivo: Array<{ motivo: string; count: number; value: number; pct: number }>;
  /** top 10 por valor, rank 1-10 */
  top10Produtos: Array<{ rank: number; produto: string; qty: number; value: number }>;
}

export interface GeneratePerdasPdfParams {
  entries: PerdasEntry[];
  periodoLabel: string;       // ex: "01/05/2026 – 31/05/2026"
  lojaLabel: string;          // ex: "Momma Asa Sul" ou "Todas as lojas"
  motivosLabel: string;       // ex: "Vencido, Quebra" ou "Todos"
  dividirEmSemanas?: boolean; // default false
  dateStart?: string;         // yyyy-MM-dd — necessário se dividirEmSemanas=true
  dateEnd?: string;           // yyyy-MM-dd
}

interface WeekBucket {
  index: number;          // 1, 2, 3...
  label: string;          // "Semana 1 — 01/05 a 07/05/2026"
  trendLabel: string;     // "S1" para eixo X do gráfico de tendência
  trendSubLabel: string;  // "01-07/05" linha de baixo do eixo
  start: Date;
  end: Date;
  entries: PerdasEntry[];
  aggregate: PerdasAggregate;
}

// ───────────────────────── HELPER PURO (TESTÁVEL) ─────────────────────────

export function aggregatePerdas(entries: PerdasEntry[]): PerdasAggregate {
  if (entries.length === 0) {
    return {
      totalValue: 0,
      totalRecords: 0,
      ticketMedio: 0,
      produtoCritico: '-',
      byMotivo: [],
      top10Produtos: [],
    };
  }

  const totalValue = entries.reduce((s, e) => s + e.val, 0);
  const totalRecords = entries.length;

  // Agrega por motivo
  const motivoMap = new Map<string, { count: number; value: number }>();
  for (const e of entries) {
    const m = e.motivo_perda || 'Não Informado';
    const cur = motivoMap.get(m) ?? { count: 0, value: 0 };
    motivoMap.set(m, { count: cur.count + 1, value: cur.value + e.val });
  }

  const byMotivo = Array.from(motivoMap.entries())
    .map(([motivo, d]) => ({
      motivo,
      count: d.count,
      value: d.value,
      pct: totalValue > 0 ? (d.value / totalValue) * 100 : 0,
    }))
    .sort((a, b) => b.value - a.value);

  // Agrega por produto (valor e qtd)
  const prodMap = new Map<string, { qty: number; value: number }>();
  for (const e of entries) {
    const p = e.prod || 'Desconhecido';
    const cur = prodMap.get(p) ?? { qty: 0, value: 0 };
    prodMap.set(p, { qty: cur.qty + e.qty, value: cur.value + e.val });
  }

  const sortedProds = Array.from(prodMap.entries())
    .sort((a, b) => b[1].value - a[1].value);

  const produtoCritico = sortedProds.length > 0 ? sortedProds[0][0] : '-';

  const top10Produtos = sortedProds.slice(0, 10).map(([produto, d], i) => ({
    rank: i + 1,
    produto,
    qty: d.qty,
    value: d.value,
  }));

  return {
    totalValue,
    totalRecords,
    ticketMedio: totalRecords > 0 ? totalValue / totalRecords : 0,
    produtoCritico,
    byMotivo,
    top10Produtos,
  };
}

/** Divide entries em buckets de 7 dias a partir de start até end (inclusive). */
export function splitIntoWeeks(
  entries: PerdasEntry[],
  start: Date,
  end: Date,
): WeekBucket[] {
  const buckets: WeekBucket[] = [];
  let cursor = new Date(start);
  let index = 1;

  while (cursor <= end) {
    const bucketStart = new Date(cursor);
    const bucketEnd = new Date(Math.min(addDays(cursor, 6).getTime(), end.getTime()));

    const bucketEntries = entries.filter(e => {
      if (!e.date) return false;
      const d = new Date(e.date);
      return d >= new Date(bucketStart.setHours(0, 0, 0, 0)) &&
             d <= new Date(bucketEnd.setHours(23, 59, 59, 999));
    });

    // Reset after comparison (setHours mutates)
    const bs = new Date(cursor);
    const be = new Date(Math.min(addDays(cursor, 6).getTime(), end.getTime()));

    const startFmt = format(bs, 'dd/MM', { locale: ptBR });
    const endFmt = format(be, 'dd/MM/yyyy', { locale: ptBR });
    const trendSubLabel = `${format(bs, 'dd', { locale: ptBR })}-${format(be, 'dd/MM', { locale: ptBR })}`;

    buckets.push({
      index,
      label: `Semana ${index} — ${startFmt} a ${endFmt}`,
      trendLabel: `S${index}`,
      trendSubLabel,
      start: bs,
      end: be,
      entries: bucketEntries,
      aggregate: aggregatePerdas(bucketEntries),
    });

    cursor = addDays(be, 1);
    index++;
  }

  return buckets;
}

// ───────────────────────── HELPERS LOCAIS DE PDF ─────────────────────────
// Replicados (não importados de outra feature) para respeitar boundaries FSD.

const MOMMA_GREEN: [number, number, number] = [87, 113, 91];
const MOMMA_GREEN_DARK: [number, number, number] = [30, 37, 31];
const MOMMA_GREEN_SOFT: [number, number, number] = [74, 85, 76];

const currencyFmt = (v: number): string =>
  v.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });

const pctFmt = (v: number): string =>
  v.toLocaleString('pt-BR', { minimumFractionDigits: 1, maximumFractionDigits: 1 }) + '%';

const qtyFmt = (v: number): string =>
  v.toLocaleString('pt-BR', { minimumFractionDigits: 0, maximumFractionDigits: 2 });

const loadImage = (url: string): Promise<HTMLImageElement> =>
  new Promise((resolve, reject) => {
    const img = new Image();
    img.crossOrigin = 'Anonymous';
    img.onload = () => resolve(img);
    img.onerror = () => reject(new Error(`Failed to load image: ${url}`));
    img.src = url;
  });

/**
 * Garante espaço vertical suficiente. Se não couber, vira página e retorna 52.
 */
function ensureSpace(
  doc: jsPDF,
  cursorY: number,
  neededMm: number,
  pageHeight: number,
  drawPageExtras: (hookData: { pageNumber?: number }) => void,
): number {
  if (cursorY + neededMm > pageHeight - 22) {
    doc.addPage();
    drawPageExtras({ pageNumber: doc.getNumberOfPages() });
    return 52;
  }
  return cursorY;
}

/**
 * Desenha barras horizontais para uma lista de itens.
 * Retorna o Y após o último elemento.
 */
function drawHorizontalBars(
  doc: jsPDF,
  items: Array<{ label: string; value: number; displayValue: string }>,
  x: number,
  y: number,
  totalWidth: number,
  barHeight = 4.5,
  gap = 2.5,
  barColor: [number, number, number] = MOMMA_GREEN,
): number {
  if (items.length === 0) return y;

  const maxVal = Math.max(...items.map(i => i.value), 1);
  const labelWidth = 30;
  const valueWidth = 22;
  const barAreaWidth = totalWidth - labelWidth - valueWidth;
  let curY = y;

  for (const item of items) {
    // Label (max 15 chars)
    const labelTxt = item.label.length > 15 ? item.label.substring(0, 14) + '…' : item.label;
    doc.setFont('helvetica', 'normal');
    doc.setFontSize(7);
    doc.setTextColor(80, 80, 80);
    doc.text(labelTxt, x, curY + barHeight - 1);

    const barX = x + labelWidth;

    // Background bar
    doc.setFillColor(235, 235, 235);
    doc.rect(barX, curY, barAreaWidth, barHeight, 'F');

    // Colored bar (proportional)
    if (item.value > 0) {
      const filledW = Math.max(1, (item.value / maxVal) * barAreaWidth);
      doc.setFillColor(...barColor);
      doc.rect(barX, curY, filledW, barHeight, 'F');
    }

    // Value label (right)
    doc.setFont('helvetica', 'bold');
    doc.setFontSize(7);
    doc.setTextColor(...MOMMA_GREEN_DARK);
    doc.text(item.displayValue, x + totalWidth, curY + barHeight - 1, { align: 'right' });

    curY += barHeight + gap;
  }

  return curY;
}

/**
 * Desenha barras verticais para dados de tendência.
 */
function drawVerticalBars(
  doc: jsPDF,
  items: Array<{ trendLabel: string; trendSubLabel: string; value: number; displayValue: string }>,
  x: number,
  y: number,
  chartWidth: number,
  chartHeight: number,
  barColor: [number, number, number] = MOMMA_GREEN,
): void {
  if (items.length === 0) return;

  const hasData = items.some(i => i.value > 0);
  if (!hasData) return;

  const maxVal = Math.max(...items.map(i => i.value), 1);
  const n = items.length;
  const slotW = chartWidth / n;
  const barW = slotW * 0.6;
  const axisLabelH = 12; // height reserved below chart for labels
  const drawH = chartHeight - axisLabelH;

  // Baseline
  doc.setDrawColor(200, 200, 200);
  doc.setLineWidth(0.3);
  doc.line(x, y + drawH, x + chartWidth, y + drawH);

  for (let i = 0; i < items.length; i++) {
    const item = items[i];
    const slotX = x + i * slotW;
    const barX = slotX + (slotW - barW) / 2;
    const barH = item.value > 0 ? Math.max(1, (item.value / maxVal) * drawH) : 0;
    const barY = y + drawH - barH;

    // Draw bar
    if (barH > 0) {
      doc.setFillColor(...barColor);
      doc.rect(barX, barY, barW, barH, 'F');
    }

    // Value label above bar (only if bar is tall enough)
    if (barH > 6) {
      doc.setFont('helvetica', 'bold');
      doc.setFontSize(6);
      doc.setTextColor(...MOMMA_GREEN_DARK);
      doc.text(item.displayValue, barX + barW / 2, barY - 1, { align: 'center' });
    }

    // Axis labels below baseline
    const labelCenterX = slotX + slotW / 2;
    doc.setFont('helvetica', 'bold');
    doc.setFontSize(7);
    doc.setTextColor(80, 80, 80);
    doc.text(item.trendLabel, labelCenterX, y + drawH + 5, { align: 'center' });

    doc.setFont('helvetica', 'normal');
    doc.setFontSize(6);
    doc.setTextColor(120, 120, 120);
    doc.text(item.trendSubLabel, labelCenterX, y + drawH + 10, { align: 'center' });
  }
}

// ───────────────────────── GERADOR DE PDF ─────────────────────────

export async function generatePerdasPdf(params: GeneratePerdasPdfParams): Promise<void> {
  const { entries, periodoLabel, lojaLabel, motivosLabel, dividirEmSemanas = false, dateStart, dateEnd } = params;
  const agg = aggregatePerdas(entries);

  const logoHeader = await loadImage('/logo sistema/01. Reduzida 5.png').catch(() => null);
  const watermarkLogo = await loadImage('/logo sistema/android-chrome-512x512.png').catch(() => null);

  const doc = new jsPDF('p', 'mm', 'a4');
  const pageWidth = doc.internal.pageSize.getWidth();
  const pageHeight = doc.internal.pageSize.getHeight();

  const subtitulo = dividirEmSemanas ? 'ANÁLISE SEMANAL' : 'ANÁLISE ESTRATÉGICA';

  // ───────────────────────── HEADER, FOOTER & WATERMARK POR PÁGINA ─────────────────────────
  const drawPageExtras = (hookData: { pageNumber?: number }) => {
    const currentPage = hookData.pageNumber || 1;

    // Bordas premium (dupla linha)
    doc.setDrawColor(...MOMMA_GREEN);
    doc.setLineWidth(0.5);
    doc.roundedRect(10, 10, pageWidth - 20, pageHeight - 20, 2, 2, 'S');
    doc.setLineWidth(0.2);
    doc.roundedRect(12, 12, pageWidth - 24, pageHeight - 24, 2, 2, 'S');

    // Logo cabeçalho — preserva aspect ratio, max 18mm altura
    if (logoHeader) {
      const ratio = logoHeader.height / logoHeader.width;
      let expectedWidth = 45;
      let expectedHeight = expectedWidth * ratio;
      if (expectedHeight > 18) {
        expectedHeight = 18;
        expectedWidth = expectedHeight / ratio;
      }
      doc.addImage(logoHeader, 'PNG', 15, 15, expectedWidth, expectedHeight);
    }

    // Título e subtítulo (alinhados à direita)
    doc.setFont('helvetica', 'bold');
    doc.setTextColor(...MOMMA_GREEN_DARK);
    doc.setFontSize(16);
    doc.text('RELATÓRIO DE PERDAS', pageWidth - 15, 20, { align: 'right' });

    doc.setFont('helvetica', 'normal');
    doc.setFontSize(9);
    doc.setTextColor(...MOMMA_GREEN);
    doc.text(subtitulo, pageWidth - 15, 25, { align: 'right' });

    doc.setTextColor(...MOMMA_GREEN_SOFT);
    doc.setFontSize(8);
    doc.text(`Período: ${periodoLabel}`, pageWidth - 15, 31, { align: 'right' });
    doc.text(`Loja: ${lojaLabel}`, pageWidth - 15, 35, { align: 'right' });
    doc.text(`Motivos: ${motivosLabel}`, pageWidth - 15, 39, { align: 'right' });

    // Linha separadora abaixo do header
    doc.setDrawColor(...MOMMA_GREEN);
    doc.setLineWidth(0.5);
    doc.line(15, 43, pageWidth - 15, 43);

    // Footer com paginação
    doc.setFont('helvetica', 'normal');
    doc.setFontSize(8);
    doc.setTextColor(...MOMMA_GREEN);
    const totalPages = doc.getNumberOfPages();
    doc.text(
      `Relatório de Perdas Momma • Emissão: ${format(new Date(), "dd/MM/yyyy 'às' HH:mm", { locale: ptBR })} • Pág. ${currentPage}/${totalPages}`,
      pageWidth / 2,
      pageHeight - 12,
      { align: 'center' },
    );

    // Watermark sutil ao centro
    if (watermarkLogo) {
      try {
        doc.setGState(new GState({ opacity: 0.08 }));
        const wSize = 200;
        doc.addImage(
          watermarkLogo,
          'PNG',
          (pageWidth - wSize) / 2,
          (pageHeight - wSize) / 2,
          wSize,
          wSize,
        );
        doc.setGState(new GState({ opacity: 1.0 }));
      } catch {
        /* fallback silencioso */
      }
    }
  };

  // Página 1: header desenhado manualmente
  drawPageExtras({ pageNumber: 1 });

  // ───────────────────────── RESUMO EXECUTIVO ─────────────────────────
  let cursorY = 52;

  doc.setFont('helvetica', 'bold');
  doc.setFontSize(11);
  doc.setTextColor(...MOMMA_GREEN);
  doc.text('RESUMO EXECUTIVO DO PERÍODO', 15, cursorY);
  cursorY += 5;

  const boxX = 15;
  const boxW = pageWidth - 30;
  const boxH = 22;

  doc.setFillColor(248, 250, 248);
  doc.setDrawColor(...MOMMA_GREEN);
  doc.setLineWidth(0.4);
  doc.roundedRect(boxX, cursorY, boxW, boxH, 2, 2, 'FD');

  const colW = boxW / 4;

  const drawMetric = (label: string, value: string, colIndex: number) => {
    doc.setFont('helvetica', 'normal');
    doc.setFontSize(8);
    doc.setTextColor(120, 120, 120);
    doc.text(label, boxX + colW * colIndex + 4, cursorY + 6);
    doc.setFont('helvetica', 'bold');
    doc.setFontSize(11);
    doc.setTextColor(...MOMMA_GREEN_DARK);
    const maxWidth = colW - 8;
    const truncated = doc.getStringUnitWidth(value) * 11 / doc.internal.scaleFactor > maxWidth
      ? value.substring(0, 18) + '…'
      : value;
    doc.text(truncated, boxX + colW * colIndex + 4, cursorY + 14);
  };

  drawMetric('PREJUÍZO TOTAL', currencyFmt(agg.totalValue), 0);
  drawMetric('REGISTROS', String(agg.totalRecords), 1);
  drawMetric('TICKET MÉDIO', currencyFmt(agg.ticketMedio), 2);
  const prodLabel = agg.produtoCritico.length > 20
    ? agg.produtoCritico.substring(0, 20) + '…'
    : agg.produtoCritico;
  drawMetric('PRODUTO CRÍTICO', prodLabel, 3);

  cursorY += boxH + 8;

  // ───────────────────────── MODO SEMANAL ─────────────────────────
  if (dividirEmSemanas && dateStart && dateEnd) {
    const weeks = splitIntoWeeks(
      entries,
      new Date(dateStart + 'T00:00:00'),
      new Date(dateEnd + 'T00:00:00'),
    );

    // Se não há semanas ou só 1, cai para modo consolidado
    if (weeks.length > 0) {
      // ── Seção: TENDÊNCIA SEMANAL ──
      cursorY = ensureSpace(doc, cursorY, 55, pageHeight, drawPageExtras);

      doc.setFont('helvetica', 'bold');
      doc.setFontSize(11);
      doc.setTextColor(...MOMMA_GREEN);
      doc.text('TENDÊNCIA SEMANAL', 15, cursorY);
      cursorY += 3;

      const trendData = weeks.map(w => ({
        trendLabel: w.trendLabel,
        trendSubLabel: w.trendSubLabel,
        value: w.aggregate.totalValue,
        displayValue: w.aggregate.totalValue > 0 ? currencyFmt(w.aggregate.totalValue) : 'R$ 0',
      }));

      drawVerticalBars(doc, trendData, 15, cursorY, pageWidth - 30, 38);
      cursorY += 38 + 12 + 10;

      // ── Por semana ──
      for (let wi = 0; wi < weeks.length; wi++) {
        const week = weeks[wi];
        const prevWeek = wi > 0 ? weeks[wi - 1] : null;

        // Estimativa de espaço mínimo para cabeçalho + KPIs
        cursorY = ensureSpace(doc, cursorY, 65, pageHeight, drawPageExtras);

        // Cabeçalho da semana
        doc.setFillColor(...MOMMA_GREEN);
        doc.rect(15, cursorY, pageWidth - 30, 7, 'F');
        doc.setFont('helvetica', 'bold');
        doc.setFontSize(9);
        doc.setTextColor(255, 255, 255);
        doc.text(week.label, pageWidth / 2, cursorY + 5, { align: 'center' });
        cursorY += 7 + 3;

        // KPIs da semana (caixa compacta 18mm)
        const wBoxH = 18;
        doc.setFillColor(248, 250, 248);
        doc.setDrawColor(...MOMMA_GREEN);
        doc.setLineWidth(0.3);
        doc.roundedRect(15, cursorY, pageWidth - 30, wBoxH, 2, 2, 'FD');

        const wColW = (pageWidth - 30) / 4;

        const drawWeekMetric = (label: string, value: string, colIndex: number) => {
          const mx = 15 + wColW * colIndex + 3;
          doc.setFont('helvetica', 'normal');
          doc.setFontSize(7);
          doc.setTextColor(120, 120, 120);
          doc.text(label, mx, cursorY + 5);
          doc.setFont('helvetica', 'bold');
          doc.setFontSize(10);
          doc.setTextColor(...MOMMA_GREEN_DARK);
          const maxW = wColW - 6;
          const txt = doc.getStringUnitWidth(value) * 10 / doc.internal.scaleFactor > maxW
            ? value.substring(0, 14) + '…'
            : value;
          doc.text(txt, mx, cursorY + 12);
        };

        const wAgg = week.aggregate;
        const wTicket = wAgg.totalRecords > 0 ? wAgg.totalValue / wAgg.totalRecords : 0;
        const wCritico = wAgg.produtoCritico.length > 14
          ? wAgg.produtoCritico.substring(0, 14) + '…'
          : wAgg.produtoCritico;

        drawWeekMetric('PREJUÍZO', currencyFmt(wAgg.totalValue), 0);
        drawWeekMetric('REGISTROS', String(wAgg.totalRecords), 1);
        drawWeekMetric('TICKET MÉDIO', currencyFmt(wTicket), 2);
        drawWeekMetric('PRODUTO CRÍTICO', wCritico, 3);

        // Delta em relação à semana anterior (apenas no prejuízo)
        if (prevWeek && prevWeek.aggregate.totalValue > 0) {
          const delta = ((wAgg.totalValue - prevWeek.aggregate.totalValue) / prevWeek.aggregate.totalValue) * 100;
          const isImproved = delta < 0; // perda menor = melhora
          const deltaText = (isImproved ? '▼ ' : '▲ ') + Math.abs(delta).toFixed(1) + '%';
          doc.setFont('helvetica', 'bold');
          doc.setFontSize(7);
          doc.setTextColor(...(isImproved ? ([34, 197, 94] as [number, number, number]) : ([239, 68, 68] as [number, number, number])));
          doc.text(deltaText, 15 + 3, cursorY + 17);
        }

        cursorY += wBoxH + 4;

        // Gráficos lado a lado: POR MOTIVO | TOP PRODUTOS
        const colAvail = pageWidth - 30; // 180mm
        const colEach = 87;
        const colGap = colAvail - colEach * 2; // remaining gap between cols

        const byMotivoItems = wAgg.byMotivo.map(m => ({
          label: m.motivo,
          value: m.value,
          displayValue: currencyFmt(m.value),
        }));

        const top5Items = wAgg.top10Produtos.slice(0, 5).map(p => ({
          label: p.produto,
          value: p.value,
          displayValue: currencyFmt(p.value),
        }));

        const rowsCount = Math.max(byMotivoItems.length, Math.min(wAgg.top10Produtos.length, 5));
        const chartNeeded = rowsCount * (4.5 + 2.5) + 20;

        cursorY = ensureSpace(doc, cursorY, chartNeeded, pageHeight, drawPageExtras);

        const colXRight = 15 + colEach + colGap;

        // Label esquerda
        doc.setFont('helvetica', 'bold');
        doc.setFontSize(8);
        doc.setTextColor(...MOMMA_GREEN);
        doc.text('POR MOTIVO', 15, cursorY + 4);

        // Label direita
        doc.text('TOP PRODUTOS', colXRight, cursorY + 4);

        const graphStartY = cursorY + 6;

        drawHorizontalBars(doc, byMotivoItems, 15, graphStartY, colEach, 4.5, 2.5, MOMMA_GREEN);
        drawHorizontalBars(doc, top5Items, colXRight, graphStartY, colEach, 4.5, 2.5, [87, 113, 91]);

        const chartH = rowsCount * (4.5 + 2.5);
        cursorY = graphStartY + chartH + 8;
      }

      // Após loop semanal, persistir e retornar
      const slug = periodoLabel.replace(/[^a-zA-Z0-9]/g, '_');
      doc.save(`perdas_semanal_${slug}.pdf`);
      return;
    }
    // fallthrough para modo consolidado se weeks.length === 0
  }

  // ───────────────────────── MODO CONSOLIDADO ─────────────────────────

  // Seção: TENDÊNCIA DO PERÍODO
  cursorY = ensureSpace(doc, cursorY, 55, pageHeight, drawPageExtras);

  doc.setFont('helvetica', 'bold');
  doc.setFontSize(11);
  doc.setTextColor(...MOMMA_GREEN);
  doc.text('TENDÊNCIA DO PERÍODO', 15, cursorY);
  cursorY += 3;

  // Monta série temporal para o gráfico de tendência
  if (dateStart && dateEnd) {
    const start = new Date(dateStart + 'T00:00:00');
    const end = new Date(dateEnd + 'T00:00:00');
    const diffDays = Math.round((end.getTime() - start.getTime()) / (1000 * 60 * 60 * 24)) + 1;

    // Agrupamento: por dia se ≤60, por semana se >60
    const byDayMap = new Map<string, number>();

    if (diffDays <= 60) {
      for (const e of entries) {
        if (!e.date) continue;
        const dayKey = e.date.substring(0, 10);
        byDayMap.set(dayKey, (byDayMap.get(dayKey) ?? 0) + e.val);
      }
    } else {
      // Agrupa por semana de 7 dias a partir de start
      const weekBuckets = splitIntoWeeks(entries, start, end);
      for (const wb of weekBuckets) {
        byDayMap.set(wb.trendLabel, wb.aggregate.totalValue);
      }
    }

    let trendPoints = Array.from(byDayMap.entries())
      .sort((a, b) => a[0].localeCompare(b[0]))
      .map(([key, val]) => {
        let label = key;
        let sub = '';
        if (diffDays <= 60 && key.length === 10) {
          try {
            const d = new Date(key + 'T12:00:00');
            label = format(d, 'dd/MM', { locale: ptBR });
            sub = format(d, 'EEE', { locale: ptBR });
          } catch {
            /* keep raw key */
          }
        } else {
          sub = key;
          label = key;
        }
        return {
          trendLabel: label,
          trendSubLabel: sub,
          value: val,
          displayValue: val > 0 ? currencyFmt(val) : 'R$ 0',
        };
      });

    // Limitar a 12 pontos
    if (trendPoints.length > 12) {
      const step = Math.ceil(trendPoints.length / 12);
      const grouped: typeof trendPoints = [];
      for (let i = 0; i < trendPoints.length; i += step) {
        const chunk = trendPoints.slice(i, i + step);
        const total = chunk.reduce((s, p) => s + p.value, 0);
        grouped.push({
          trendLabel: chunk[0].trendLabel,
          trendSubLabel: chunk[chunk.length - 1].trendSubLabel,
          value: total,
          displayValue: total > 0 ? currencyFmt(total) : 'R$ 0',
        });
      }
      trendPoints = grouped;
    }

    if (trendPoints.length > 0) {
      drawVerticalBars(doc, trendPoints, 15, cursorY, pageWidth - 30, 35);
      cursorY += 35 + 12 + 10;
    } else {
      cursorY += 8;
    }
  } else {
    cursorY += 8;
  }

  // ── SEÇÃO 2: DISTRIBUIÇÃO POR MOTIVO ──
  const motiLength = agg.byMotivo.length;
  cursorY = ensureSpace(doc, cursorY, 30 + motiLength * 7, pageHeight, drawPageExtras);

  doc.setFont('helvetica', 'bold');
  doc.setFontSize(11);
  doc.setTextColor(...MOMMA_GREEN);
  doc.text('DISTRIBUIÇÃO POR MOTIVO', 15, cursorY);
  cursorY += 3;

  // Gráfico de barras horizontais
  if (motiLength > 0) {
    const motiItems = agg.byMotivo.map(m => ({
      label: m.motivo,
      value: m.value,
      displayValue: currencyFmt(m.value),
    }));
    const motiBarH = motiLength * (5 + 3);
    cursorY = ensureSpace(doc, cursorY, motiBarH + 6, pageHeight, drawPageExtras);
    drawHorizontalBars(doc, motiItems, 15, cursorY, pageWidth - 30, 5, 3);
    cursorY += motiBarH + 6;
  }

  // Tabela de motivos
  const motivoBody = agg.byMotivo.map((m) => [
    m.motivo,
    String(m.count),
    currencyFmt(m.value),
    pctFmt(m.pct),
  ]);
  motivoBody.push([
    'TOTAL',
    String(agg.totalRecords),
    currencyFmt(agg.totalValue),
    '100,0%',
  ]);

  autoTable(doc, {
    startY: cursorY,
    head: [['Motivo', 'Registros', 'Valor (R$)', '% do Total']],
    body: motivoBody,
    theme: 'plain',
    styles: {
      fontSize: 8,
      font: 'helvetica',
      cellPadding: { top: 1.8, bottom: 1.8, left: 2, right: 2 },
      textColor: [60, 60, 60],
      lineColor: [230, 230, 230],
      lineWidth: { bottom: 0.1 },
    },
    headStyles: {
      fillColor: MOMMA_GREEN,
      textColor: [255, 255, 255],
      fontStyle: 'bold',
      fontSize: 8.5,
      cellPadding: { top: 2.5, bottom: 2.5, left: 2, right: 2 },
      lineWidth: 0,
    },
    alternateRowStyles: { fillColor: [248, 250, 248] },
    columnStyles: {
      0: { cellWidth: 'auto' },
      1: { cellWidth: 25, halign: 'right' },
      2: { cellWidth: 40, halign: 'right', fontStyle: 'bold' },
      3: { cellWidth: 22, halign: 'right' },
    },
    didParseCell: (data) => {
      if (data.section === 'body' && data.row.index === motivoBody.length - 1) {
        data.cell.styles.fontStyle = 'bold';
        data.cell.styles.fillColor = [236, 242, 237];
        data.cell.styles.textColor = MOMMA_GREEN_DARK;
      }
    },
    didDrawPage: (hk) => {
      if (hk.pageNumber > 1) drawPageExtras(hk);
    },
    margin: { top: 50, left: 15, right: 15, bottom: 20 },
  });

  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  cursorY = (doc as any).lastAutoTable.finalY + 8;

  // ── SEÇÃO 3: TOP 10 PRODUTOS ──
  const top10Count = Math.min(agg.top10Produtos.length, 10);
  cursorY = ensureSpace(doc, cursorY, 30 + top10Count * 7, pageHeight, drawPageExtras);

  doc.setFont('helvetica', 'bold');
  doc.setFontSize(11);
  doc.setTextColor(...MOMMA_GREEN);
  doc.text('TOP 10 PRODUTOS POR PREJUÍZO', 15, cursorY);
  cursorY += 3;

  // Gráfico de barras horizontais para top produtos
  if (top10Count > 0) {
    const top10Items = agg.top10Produtos.slice(0, 10).map(p => ({
      label: p.produto,
      value: p.value,
      displayValue: currencyFmt(p.value),
    }));
    const top10BarH = top10Count * (5 + 3);
    cursorY = ensureSpace(doc, cursorY, top10BarH + 6, pageHeight, drawPageExtras);
    drawHorizontalBars(doc, top10Items, 15, cursorY, pageWidth - 30, 5, 3, [87, 113, 91]);
    cursorY += top10BarH + 6;
  }

  // Tabela top 10
  const top10Body = agg.top10Produtos.map((p) => [
    String(p.rank),
    p.produto,
    qtyFmt(p.qty),
    currencyFmt(p.value),
  ]);

  autoTable(doc, {
    startY: cursorY,
    head: [['#', 'Produto', 'Qtd', 'Valor (R$)']],
    body: top10Body,
    theme: 'plain',
    styles: {
      fontSize: 8,
      font: 'helvetica',
      cellPadding: { top: 1.8, bottom: 1.8, left: 2, right: 2 },
      textColor: [60, 60, 60],
      lineColor: [230, 230, 230],
      lineWidth: { bottom: 0.1 },
    },
    headStyles: {
      fillColor: MOMMA_GREEN,
      textColor: [255, 255, 255],
      fontStyle: 'bold',
      fontSize: 8.5,
      cellPadding: { top: 2.5, bottom: 2.5, left: 2, right: 2 },
      lineWidth: 0,
    },
    alternateRowStyles: { fillColor: [248, 250, 248] },
    columnStyles: {
      0: { cellWidth: 12, halign: 'center', fontStyle: 'bold' },
      1: { cellWidth: 'auto' },
      2: { cellWidth: 25, halign: 'right' },
      3: { cellWidth: 40, halign: 'right', fontStyle: 'bold' },
    },
    didDrawPage: (hk) => {
      if (hk.pageNumber > 1) drawPageExtras(hk);
    },
    margin: { top: 50, left: 15, right: 15, bottom: 20 },
  });

  // ───────────────────────── PERSISTÊNCIA ─────────────────────────
  const slug = periodoLabel.replace(/[^a-zA-Z0-9]/g, '_');
  doc.save(`perdas_${slug}.pdf`);
}

